      doReturn((String) null, (String) null).when(lookup).toString();
      doReturn("}").when(lookup).apply(anyString());

      StringSubstitutor returned = substitutor.setVariableResolver(lookup);
      returned.replace(template);

      assertEquals(DEFAULT_ESCAPE, returned.getEscapeChar());
  }
